# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["这轮做的是机械审计：把 config.py 里每一个字段拉出来，查它在运行时代码里有没有读取点。","结论是两个字段从来没被读过，其中一个是整个系统的核心概念。","","=== 一、审计方法先被自己证伪了一次 ===","","第一版脚本报出 4 个死字段。但我立刻想到两个假阳性来源：","  1) trend_hysteresis_pct 是用 getattr(cfg, \"trend_hysteresis_pct\", 0.0) 读的，","     字段名在字符串里，正则匹配 .字段 抓不到；","  2) spot_taker_fee 是在 config.py 自己的方法里 self.spot_taker_fee 读的，","     而我把 config.py 整个文件排除掉了。","","修掉这两类漏检后，4 个变成 2 个。教训还是那句：验证手段本身会撒谎。","","=== 二、tick_bucket_ms：一个改不动的旋钮 ===","","    config.py:17             tick_bucket_ms: int = 3000","    config/config.yaml:7     tick_bucket_ms: 3000   # 3s 准实时（用户口径）","","load() 里的 _apply 会把它真的写进字段——然后整个 ai_trader/ 没有一处读它。","3 秒桶实际由模块常量 INTERVALS_MS 和 market/agg.py 的断言决定：","    INTERVALS_MS = [3000, 15000, ...]","    assert 3000 in intervals, 3s 必须是原子周期","","所以任何人把 tick_bucket_ms 改成 1000，会得到一个看起来改好了、实际一点没变的系统。","配置文件里那句注释 3s 准实时（用户口径） 更是加深了误解。","","判断：这是不该接线而不是没接线。3 秒是结构不变量——","engine、paper、signals、ws_server 到处硬编码 3000，改成可调只会让断言炸。","所以删掉字段和 yaml 行，原地留一条说明。","","=== 三、initial_leverage = 150：scalp 时代的危险残留 ===","","    config.py:135   initial_leverage: int = 150   # 账户侧杠杆设置","","零读取。趋势策略实际用的是 trend_leverage（现货 1x）。","这个比死字段更危险：名字和注释都在暗示账户正在用 150 倍杠杆，","而真实值是 1 倍。删掉它是为了避免有人照着它做判断。","","=== 四、顺手加固：yaml 里的拼错会被静默吞掉 ===","","_apply 里有一句 if not hasattr(obj, k): continue ——","config.yaml 里键名拼错不会报错，只会被跳过。","这和死字段是同一类病：一个不生效的旋钮。","","=== 五、验证 ===","","新增 tests/test_no_dead_config.py（4 条）：","  1. 每个配置字段必须有读取点（含 getattr 字符串形式）","  2. 豁免清单不能超过 4 条（防止它变成垃圾桶）","  3. 检测器自检：必须认得 getattr 读法、必须不把无关文本当读取","  4. config.yaml 的每个键必须真实存在","","变异验证 3/3 红：","  加一个没人读的字段              -> 红","  删掉 trend_leverage 唯一读取点  -> 红","  yaml 键名拼错                   -> 红","","（顺带记一个我自己的失误：最初用删除 trend.py 里 getattr 的方式做变异，测试没红。"," 因为删掉后该字段仍被 config.py 的 env 覆盖读着，所以绿是对的，"," 是变异设计错了，不是测试漏了。换成只有单点读取的 trend_leverage 才有效。）","","全量 401 条全绿。","","线上：重启后正常补 419 根 4h，健康自检 OK；","运行时确认 tick_bucket_ms / initial_leverage 均已不存在，","配置读出 symbol=BTCUSDT mode=paper hyst=0.20 lev=1.0 strategy=trend。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":80,"theme":"配置字段机械审计：两个从没被读过的字段，其中一个是系统核心概念","method":"枚举 config.py 全部 dataclass 字段 -> 在 ai_trader/ 里找读取点（含 getattr 字符串形式）","audit_tool_first_draft_wrong":"第一版报 4 个死字段，去掉两类假阳性后为 2 个","dead_fields":[{"field":"MarketCfg.tick_bucket_ms","line":17,"also_in_yaml":true,"verdict":"不该接线——3s 是结构不变量，删除并留说明"},{"field":"TradingCfg.initial_leverage","line":135,"value":150,"verdict":"scalp 时代残留、零读取，名字与注释误导，删除"}],"fixes":["删除 tick_bucket_ms 字段与 config.yaml 中对应行","删除 initial_leverage 字段","新增 tests/test_no_dead_config.py"],"mutation":"3/3 红：加死字段 / 删唯一读取点 / yaml 键名拼错","self_inflicted":"最初那条变异没红，是变异设计错（字段仍被 config.py env 覆盖读着），换成单点读取的字段才有效","verification":{"tests":401,"new_tests":4,"deployed":true,"healthcheck":"OK","seeded_bars":419,"runtime_check":"tick_bucket_ms=False initial_leverage=False; hyst=0.20 lev=1.0 strategy=trend"},"account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'配置字段机械审计：两个从没被读过的字段，其中一个是系统核心概念',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()